package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayRealVector.getNorm().
 */
public class ArrayRealVector_getNorm_TriageGen1Test {

    private static final double EPSILON = 1e-12;

    @Test
    public void testGetNorm_EmptyVector() {
        // The implementation uses a for-each loop on 'data'. 
        // If data is empty, sum remains 0, sqrt(0) is 0.
        ArrayRealVector vector = new ArrayRealVector(0);
        Assert.assertEquals(0.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_ZeroVector() {
        double[] data = {0.0, 0.0, 0.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(0.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_SingleElement() {
        double[] data = {5.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(5*5) = 5
        Assert.assertEquals(5.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_PositiveValues() {
        double[] data = {3.0, 4.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(3^2 + 4^2) = sqrt(9 + 16) = 5
        Assert.assertEquals(5.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_NegativeValues() {
        double[] data = {-3.0, -4.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt((-3)^2 + (-4)^2) = 5
        Assert.assertEquals(5.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_MixedValues() {
        double[] data = {1.0, -2.0, 2.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(1^2 + (-2)^2 + 2^2) = sqrt(1 + 4 + 4) = 3
        Assert.assertEquals(3.0, vector.getNorm(), EPSILON);
    }

    @Test
    public void testGetNorm_LargeValues() {
        double[] data = {1e10, 1e10};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(1e20 + 1e20) = sqrt(2e20) = 1e10 * sqrt(2)
        double expected = Math.sqrt(2.0) * 1e10;
        Assert.assertEquals(expected, vector.getNorm(), 1e-2); // Using larger epsilon for large scale
    }

    @Test
    public void testGetNorm_SmallValues() {
        double[] data = {1e-10, 1e-10};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(1e-20 + 1e-20) = sqrt(2e-20) = 1e-10 * sqrt(2)
        double expected = Math.sqrt(2.0) * 1e-10;
        Assert.assertEquals(expected, vector.getNorm(), 1e-20);
    }

    @Test
    public void testGetNorm_WithNaN() {
        double[] data = {1.0, Double.NaN};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sum = 1 + NaN = NaN. sqrt(NaN) = NaN
        Assert.assertTrue(Double.isNaN(vector.getNorm()));
    }

    @Test
    public void testGetNorm_WithInfinity() {
        double[] data = {1.0, Double.POSITIVE_INFINITY};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sum = 1 + inf = inf. sqrt(inf) = inf
        Assert.assertEquals(Double.POSITIVE_INFINITY, vector.getNorm(), 0.0);
    }
}
